namespace TaskTree.Modules.AutoUpdater.Tests{[TestClass]public class AutoUpdaterTests{static UpdateManifest Manifest(byte[] payload,string? hash=null,long? size=null,string alg="Ed25519",string sig="not-base64"){var verifier=new HashVerifier();return new UpdateManifest("1.0.1",UpdateChannel.Stable,new DateTimeOffset(2026,6,1,0,0,0,TimeSpan.Zero),"1.0.0",100,new UpdatePackageInfo("https://updates.example.invalid/tasktree.msix",hash??verifier.ComputeSha256Hex(payload),size??payload.Length),new UpdateSignatureInfo(alg,"tasktree-stable-2026",sig),"Synthetic test manifest");}[TestMethod]public void Manifest_Parse_ValidSchema_Succeeds(){var payload=Encoding.UTF8.GetBytes("abc");var json=JsonSerializer.Serialize(Manifest(payload),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});var parsed=JsonSerializer.Deserialize<UpdateManifest>(json,new JsonSerializerOptions{PropertyNameCaseInsensitive=true});Assert.IsNotNull(parsed);Assert.AreEqual("1.0.1",parsed!.Version);}[TestMethod]public void VerifyAsync_SizeMismatch_ReturnsFalse(){var payload=Encoding.UTF8.GetBytes("abc");Assert.IsFalse(new AutoUpdater().VerifyAsync(Manifest(payload,size:999),payload).GetAwaiter().GetResult());}[TestMethod]public void VerifyAsync_HashMismatch_ReturnsFalse(){var payload=Encoding.UTF8.GetBytes("abc");Assert.IsFalse(new AutoUpdater().VerifyAsync(Manifest(payload,hash:new string('B',64)),payload).GetAwaiter().GetResult());}[TestMethod]public void VerifyAsync_SignatureMismatch_ReturnsFalse(){var payload=Encoding.UTF8.GetBytes("abc");Assert.IsFalse(new AutoUpdater().VerifyAsync(Manifest(payload),payload).GetAwaiter().GetResult());}[TestMethod]public void CheckAsync_NoLiveHttp_ReturnsNull(){Assert.IsNull(new AutoUpdater().CheckAsync().GetAwaiter().GetResult());}[TestMethod]public void ApplyAsync_ThrowsHighStub_ClearReason(){var ex=Assert.ThrowsExceptionAsync<NotImplementedException>(()=>new AutoUpdater().ApplyAsync(Manifest(Array.Empty<byte>()))).GetAwaiter().GetResult();StringAssert.Contains(ex.Message,"Add-AppxPackage");}[TestMethod]public void ImportLocalAsync_MissingBundle_ThrowsFileNotFound(){Assert.ThrowsExceptionAsync<FileNotFoundException>(()=>new AutoUpdater().ImportLocalAsync("synthetic.msix")).GetAwaiter().GetResult();}}}
